#include <stdio.h>
int main(void){int n,f,r[100],fr[20],fault=0;printf("Reference count and frames: ");scanf("%d%d",&n,&f);if(n>100||f>20||n<1||f<1)return 1;for(int j=0;j<f;j++)fr[j]=-1;printf("Reference string: ");for(int i=0;i<n;i++)scanf("%d",&r[i]);for(int i=0;i<n;i++){int hit=0;for(int j=0;j<f;j++)if(fr[j]==r[i])hit=1;if(!hit){fault++;int k=-1,far=-1;for(int j=0;j<f;j++){if(fr[j]<0){k=j;break;}int next=n;for(int x=i+1;x<n;x++)if(r[x]==fr[j]){next=x;break;}if(next>far){far=next;k=j;}}fr[k]=r[i];}printf("%d: ",r[i]);for(int j=0;j<f;j++)if(fr[j]<0)printf("- ");else printf("%d ",fr[j]);puts("");}printf("Page faults = %d\n",fault);return 0;}
